 import { gsap } from 'gsap';
import {
  Color,
  DoubleSide,
  Group,
  Mesh,
  MeshBasicNodeMaterial,
  PlaneGeometry
} from 'three/webgpu';

export default function createNode(config, ctx) {
  const colors = config.intent?.visualSpec?.colors || config.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const group = new Group();
  group.name = (config.id || 'journal-thumb') + '-card';

  const width = 2.0;
  const height = width * (320 / 512);
  const captionH = 0.25;
  const imageH = height - captionH;

  // Backing
  const backGeo = new PlaneGeometry(width, height);
  const backMat = new MeshBasicNodeMaterial({
    color: new Color(colors.ink),
    transparent: true,
    opacity: 0.6
  });
  const back = new Mesh(backGeo, backMat);
  group.add(back);

  // Focus accent edge
  const edgeGeo = new PlaneGeometry(width + 0.04, height + 0.04);
  const edgeMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent),
    transparent: true,
    opacity: 0,
    side: DoubleSide
  });
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.z = -0.005;
  group.add(edge);

  // Caption strip
  const stripGeo = new PlaneGeometry(width, captionH);
  const stripMat = new MeshBasicNodeMaterial({
    color: new Color(colors.surface),
    transparent: true,
    opacity: 0.95
  });
  const strip = new Mesh(stripGeo, stripMat);
  strip.position.y = -(height / 2) + (captionH / 2);
  strip.position.z = 0.002;
  group.add(strip);

  // Image plane
  const imgGeo = new PlaneGeometry(width - 0.04, imageH - 0.04);
  const imgMat = new MeshBasicNodeMaterial({
    color: new Color(0xffffff),
    transparent: true,
    opacity: 1
  });
  const img = new Mesh(imgGeo, imgMat);
  img.position.y = (height / 2) - (imageH / 2) - 0.02;
  img.position.z = 0.004;
  group.add(img);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (ctx.THREE.SRGBColorSpace) tex.colorSpace = ctx.THREE.SRGBColorSpace;
      imgMat.map = tex;
      imgMat.needsUpdate = true;
    });
  }

  const activePrimitives = [];
  const primitivesList = Array.isArray(config.cinematicPrimitives)
    ? config.cinematicPrimitives
    : [];
  for (const p of primitivesList) {
    if (ctx.primitives && typeof ctx.primitives[p.name] === 'function') {
      activePrimitives.push(ctx.primitives[p.name](group, p.params || {}));
    }
  }

  const hoverTl = gsap.timeline({ paused: true }).to(group.position, {
    y: 0.15,
    duration: 0.35,
    ease: 'power2.out'
  });

  const pressTl = gsap
    .timeline({ paused: true })
    .to(group.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)'
    })
    .to(group.scale, {
      x: 1,
      y: 1,
      duration: 0.2,
      ease: 'power2.out'
    });

  const focusTl = gsap.timeline({ paused: true }).to(edgeMat, {
    opacity: 0.8,
    duration: 0.2,
    ease: 'power2.out'
  });

  group.userData.handlers = {
    hover: () => hoverTl.play(),
    out: () => hoverTl.reverse(),
    click: () => {
      pressTl.restart();
      ctx.emit('hub-journal.select', { fromId: config.id });
    },
    focus: () => focusTl.play(),
    blur: () => focusTl.reverse()
  };

  group.userData.cleanup = () => {
    hoverTl.kill();
    pressTl.kill();
    focusTl.kill();

    backGeo.dispose();
    backMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    stripGeo.dispose();
    stripMat.dispose();
    imgGeo.dispose();
    imgMat.dispose();

    if (imgMat.map) imgMat.map.dispose();

    for (const r of activePrimitives) {
      if (r && typeof r.cleanup === 'function') r.cleanup();
    }
  };

  return group;
}
